	ID      string `json:"id"`
	Status  string `json:"status"` // Must be "cancelled" for success.
}

// CancelOrder handles the cancellation of an order.
func (s *Server) cancelOrder(w http.ResponseWriter, r *http.Request) {
	var req cancelOrderRequest
	if err := decodeBody(r, &req); err != nil {
		writeError(w, http.StatusBadRequest, codeBadJSON, "request body must be valid JSON")
		return
	}

	// Validate order existence and status.
	id := req.ID
	if !s.OrderStore.Get(id) {
		writeError(w, http.StatusNotFound, codeNotFound, "order not found")
		return
	}

	if req.Status != "cancelled" {
		writeError(w, http.StatusConflict, codeConflict, "only pending orders can be cancelled")
		return
	}

	// Cancel the order.
	if s.OrderStore.SetStatus(id, "cancelled") {
		// Return the updated order.
		updatedOrder, _ := s.OrderStore.Get(id)
		writeJSON(w, http.StatusOK, map[string]any{ "data": updatedOrder })
	} else {
		writeError(w, http.StatusConflict, codeConflict, "failed to cancel order")
	}
}

