package shop

import (
	"encoding/json"
	"fmt"
	"net/http"
	"slices"
	"strings"
	"sync"
)

// Error codes used in the "code" field of every error response.
const (
	codeBadJSON          = "bad_json"
	codeBadQuery         = "bad_query"
	codeValidationFailed = "validation_failed"
	codeNotFound         = "not_found"
	codeConflict         = "conflict"
)

// All success responses wrap their payload in {"data": ...}.
type dataEnvelope struct{ Data any }  // All success responses wrap their payload in {"data": ...}.
type listEnvelope struct{ Data any; Page pageInfo }  // List responses add a "page" object next to "data".
type errorEnvelope struct{ Error apiError }  // All error responses look like {"error": {"code": ..., "message": ...}}.
type apiError struct{ Code string; Message string }

type OrderItem struct{ ProductID string; Quantity int }
type Order struct{ ID string; UserID string; Items []OrderItem; TotalCents int64; Status string }

// In-memory, concurrency-safe store of orders.
type OrderStore struct {
	mu    sync.RWMutex
	items map[string]Order
}

func NewOrderStore() *OrderStore {
	return &OrderStore{items: make(map[string]Order)}
}

// Create assigns the next ID, stores the order, and returns the stored copy.
func (st *OrderStore) Create(o Order) Order {
	st.mu.Lock()
	defer st.mu.Unlock()
	st.seq++
	o.ID = formatID("ord", st.seq)
	o.Items = slices.Clone(o.Items)
	st.items[o.ID] = o
	return o
}

// Get returns the order and whether it exists.
func (st *OrderStore) Get(id string) (Order, bool) {
	st.mu.RLock()
	defer st.mu.RUnlock()
	o, ok := st.items[id]
	return o, ok
}

// SetStatus reports whether the order existed.
func (st *OrderStore) SetStatus(id, status string) (Order, bool) {
	st.mu.Lock()
	defer st.mu.Unlock()
	o, ok := st.items[id]
	if !ok {
		return Order{}, false
	}
	o.Status = status
	st.items[id] = o
	return o, true
}

// List returns all orders sorted by ID.
func (st *OrderStore) List() []Order {
	st.mu.RLock()
	defer st.mu.RUnlock()
	out := make([]Order, 0, len(st.items))
	for _, o := range st.items {
		out = append(out, o)
	}
	slices.SortFunc(out, func(a, b Order) int { return strings.Compare(a.ID, b.ID) })
	return out
}

// Order handler for fetching a single order: GET /orders/{id}
func (s *Server) orderRoutes(mux *http.ServeMux) {
	mux.HandleFunc("GET /orders/{id}", s.handleGetOrder)
}

