	json.NewEncoder(w).Encode(data)
}

func writeList(w http.ResponseWriter, data any, page pageInfo) {
	writeJSON(w, http.StatusOK, listEnvelope{Data: data, Page: page})
}

func writeError(w http.ResponseWriter, status int, code, message string) {
	writeJSON(w, status, errorEnvelope{Error: apiError{Code: code, Message: message}}}
}

func writeNotFound(w http.ResponseWriter, kind, id string) {
	writeError(w, http.StatusNotFound, codeNotFound, fmt.Sprintf("%s %s not found", kind, id))
}

func decodeBody(r *http.Request, dst any) error {
	dec := json.NewDecoder(r.Body)
	dec.DisallowUnknownFields()
	return dec.Decode(dst)
}

const defaultLimit = 20
const maxLimit = 100

type pageParams struct{ Limit  int; Offset int }
type pageInfo struct{ Limit  int; Offset int; Total int }

// parsePage reads ?limit= and ?offset=. Handlers turn an error into a 400
func parsePage(r *http.Request) (pageParams, error) {
	p := pageParams{Limit: defaultLimit}
	q := r.URL.Query()
	if v := q.Get("limit"); v != "" {
		n, err := strconv.Atoi(v)
		if err != nil || n < 1 || n > maxLimit {
			return p, fmt.Errorf("limit must be an integer from 1 to %d", maxLimit)
		}
		p.Limit = n
	}
	if v := q.Get("offset"); v != "" {
		n, err := strconv.Atoi(v)
		if err != nil || n < 0 {
			return p, fmt.Errorf("offset must be a non-negative integer")
		}
		p.Offset = n
	}
	return p, nil
}

// paginate slices items according to p. It never returns a nil slice, so
// an empty page encodes as [] rather than null.
func paginate[T any](items []T, p pageParams) ([]T, pageInfo) {
	info := pageInfo{Limit: p.Limit, Offset: p.Offset, Total: len(items)}
	if p.Offset >= len(items) {
		return []T{}, info
	}
	end := min(p.Offset+p.Limit, len(items))
	return items[p.Offset:end], info
}

