type User struct {
	ID    string `json:"id"`
	Email string `json:"email"` // normalized email: trim whitespace and lowercase
	Name  string `json:"name"`
}

type UserStore struct {
	mu    sync.RWMutex
	items map[string]User
}

func NewUserStore() *UserStore {
	return &UserStore{items: make(map[string]User)}
}

// Create assigns the next ID, normalizes the email, stores the user, and returns the stored copy.
func (st *UserStore) Create(u User) User {
	st.mu.Lock()
	defer st.mu.Unlock()
	st.seq++
	u.Email = strings.ToLower(strings.TrimSpace(u.Email)) // normalize email
	st.items[u.ID] = u
	return u
}

// Get returns the user and a boolean indicating if the user exists.
func (st *UserStore) Get(id string) (User, bool) {
	st.mu.RLock()
	defer st.mu.RUnlock()
	u, ok := st.items[id]
	return u, ok
}

// FindByEmail matches case-insensitively and normalizes the email before matching.
func (st *UserStore) FindByEmail(email string) (User, bool) {
	st.mu.RLock()
	defer st.mu.RUnlock()
	normalizedEmail := strings.ToLower(strings.TrimSpace(email))
	for _, u := range st.items {
		if strings.EqualFold(u.Email, normalizedEmail) {
			return u, true
		}
	}
	return User{}, false
}

// List returns all users sorted by ID.
func (st *UserStore) List() []User {
	st.mu.RLock()
	defer st.mu.RUnlock()
	out := make([]User, 0, len(st.items))
	for _, u := range st.items {
		out = append(out, u)
	}
	slices.SortFunc(out, func(a, b User) int { return a.ID.Compare(b.ID) }) // Sort by ID
	return out
}

// Delete reports whether the user existed.
func (st *UserStore) Delete(id string) bool {
	st.mu.Lock()
	defer st.mu.Unlock()
	if _, ok := st.items[id]; !ok {
		return false
	}
	delete(st.items, id)
	return true
}

