	"slices"
	"strings"
	"sync"
)

type User struct {
	ID    string `json:"id"`
	Email string `json:"email"`
	Name  string `json:"name"`
}

// UserStore is an in-memory, concurrency-safe store of users.
type UserStore struct {
	mu    sync.RWMutex
	items map[string]User
	seq   int
}

func NewUserStore() *UserStore {
	return &UserStore{items: make(map[string]User)}
}

// Create assigns the next ID, stores the user, and returns the stored copy.
func (st *UserStore) Create(u User) User {
	st.mu.Lock()
	defer st.mu.Unlock()
	st.seq++
	newUser := u // Make a copy to avoid reference issues
	newUser.ID = formatID("usr", st.seq)
	st.items[newUser.ID] = newUser
	return newUser
}

// Get retrieves a user by ID.
func (st *UserStore) Get(id string) (User, bool) {
	st.mu.RLock()
	defer st.mu.RUnlock()
	user, exists := st.items[id]
	return user, exists
}

// FindByEmail matches case-insensitively.
func (st *UserStore) FindByEmail(email string) (User, bool) {
	st.mu.RLock()
	defer st.mu.RUnlock()
	for _, user := range st.items {
		if strings.EqualFold(user.Email, email) {
			return user, true
		}
	}
	return User{}, false
}

// List returns all users sorted by ID.
func (st *UserStore) List() []User {
	st.mu.RLock()
	defer st.mu.RUnlock()
	out := make([]User, 0, len(st.items))
	for _, user := range st.items {
		out = append(out, user)
	}
	slices.SortFunc(out, func(a, b User) int { return strings.Compare(a.ID, b.ID) })
	return out
}

// Delete reports whether the user existed.
func (st *UserStore) Delete(id string) bool {
	st.mu.Lock()
	defer st.mu.Unlock()
	if _, exists := st.items[id]; !exists {
		return false
	}
	delete(st.items, id)
	return true

}

// UpdateName sets the user's name and returns the updated user, false if the user does not exist.
func (st *UserStore) UpdateName(id, name string) (User, bool) {
	st.mu.Lock()
	defer st.mu.Unlock()
	if _, exists := st.items[id]; !exists {
		return User{}, false
	}
	// Create a copy of the user to avoid mutation of the original
	updatedUser := st.items[id] // This is fine because we're not directly referencing the map entry
	updatedUser.Name = name     // Update the Name field
	st.items[id] = updatedUser  // Update the map entry
	return updatedUser, true
}

